/** Native 0.6 console; all commands still pass the authenticated per-computer connection. */
final class NativeTaskConsole {
    interface Host {void route(String route);void openConversation(NativeConnection computer,String thread);Dialog sheet(String title,LinearLayout content);void error(String message);}
    private final Activity activity;private final PaneUi ui;private final NativeConnections computers;private final Host host;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private String route="tasks",computerFilter="",projectFilter="",stateFilter="unfinished",query="",formComputer="",pendingEnqueue="",pendingComputer="";
    private NativeTaskCatalog.Row selected;
    private JSONObject pendingForm;
    private boolean enqueueNeedsReview;
    private LinearLayout list;private ScrollView scroll;private TextView count;
    private EditText formCwd,formText;private Spinner formModel,formEffort;private Button enqueueButton;
    private NativeConnection formOwner;private JSONObject appliedTemplate;
    private final Runnable saveFormLater=this::saveInputs;
    private Dialog liveApprovalDialog;private NativeConnection liveApprovalComputer;private JSONObject liveApproval;
    NativeTaskConsole(Activity activity,PaneUi ui,NativeConnections computers,Host host){this.activity=activity;this.ui=ui;this.computers=computers;this.host=host;}
    boolean handles(String route){return Arrays.asList("tasks","queue","queueNew","approvals","taskDetail","templates").contains(route);}
    void detach(){saveInputs();handler.removeCallbacks(saveFormLater);list=null;count=null;formCwd=null;formText=null;formModel=null;formEffort=null;formOwner=null;enqueueButton=null;}
    void stop(){saveInputs();handler.removeCallbacksAndMessages(null);if(liveApprovalDialog!=null)liveApprovalDialog.dismiss();liveApprovalDialog=null;}
    private String text(JSONObject object,String key){return NativeTaskCatalog.text(object,key);}
    private String time(long value){if(value<=0)return "更新时间未知";if(value<100000000000L)value*=1000;return new SimpleDateFormat("MM-dd HH:mm:ss",Locale.CHINA).format(new Date(value));}
    private String queueLabel(String value){switch(value){case "pending":return "排队等待";case "dispatching":return "正在派发";case "running":return "执行中";case "waiting":return "待审批 · 占用执行槽";case "unknown":return "结果不明 · 需核对";case "completed":return "已完成";case "failed":return "失败";case "cancelled":return "已取消";default:return "未加入队列";}}
    private String runtimeLabel(String value){switch(value){case "running":return "运行中";case "waiting":return "待审批";case "failed":return "失败";case "idle":return "空闲";default:return "未知";}}
    private String goalLabel(String value){switch(value){case "active":return "实施中";case "paused":return "已暂停";case "blocked":return "受阻";case "budgetLimited":return "预算受限";case "usageLimited":return "用量受限";case "complete":return "已完成";default:return "未设置／未知";}}
    private void heading(LinearLayout body,String name,boolean back){LinearLayout row=ui.row();ui.pad(row,12,8);if(back)row.addView(ui.iconButton("back","返回任务",()->host.route("tasks")),new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));row.addView(ui.heading(name,back?22:30),new LinearLayout.LayoutParams(0,-2,1));row.addView(ui.iconButton("plus","添加排队任务",()->newTask(computers.active(),null)),new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));body.addView(row);}
    private void buttonRow(LinearLayout body,String[] labels,Runnable[] actions){HorizontalScrollView horizontal=new HorizontalScrollView(activity);horizontal.setHorizontalScrollBarEnabled(false);LinearLayout row=ui.row();ui.pad(row,16,4);for(int i=0;i<labels.length;i++){Button button=ui.button(labels[i],Color.WHITE,PaneUi.BLUE,actions[i]);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-2,ui.dp(44));params.rightMargin=ui.dp(8);row.addView(button,params);}horizontal.addView(row);body.addView(horizontal);}
    void mount(LinearLayout body,String route){saveInputs();handler.removeCallbacks(saveFormLater);this.route=route;formCwd=null;formText=null;formModel=null;formEffort=null;enqueueButton=null;formOwner=null;list=null;count=null;
        heading(body,"tasks".equals(route)?"任务中心":"queue".equals(route)?"任务队列":"approvals".equals(route)?"审批中心":"templates".equals(route)?"任务模板":"queueNew".equals(route)?"添加排队任务":"任务详情",!"tasks".equals(route));
        if("tasks".equals(route)){buttonRow(body,new String[]{"队列","审批中心","模板","立即新建会话"},new Runnable[]{()->host.route("queue"),()->host.route("approvals"),()->host.route("templates"),()->host.route("new")});buttonRow(body,new String[]{computerFilter.isEmpty()?"全部电脑":computerName(computerFilter),projectFilter.isEmpty()?"全部项目":projectFilter,"状态 · "+stateName()},new Runnable[]{this::chooseComputerFilter,this::chooseProjectFilter,this::chooseStateFilter});EditText search=ui.input("搜索任务");search.setSingleLine(true);search.setText(query);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.setMargins(ui.dp(20),ui.dp(8),ui.dp(20),ui.dp(8));body.addView(search,params);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();render();}public void afterTextChanged(Editable e){}});}
        count=ui.text("",12,PaneUi.MUTED);ui.pad(count,20,5);body.addView(count);scroll=new ScrollView(activity);scroll.setFillViewport(true);list=ui.column();ui.pad(list,20,12);scroll.addView(list);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if("queueNew".equals(route))form();else render();
    }
    private String computerName(String id){NativeConnection c=computers.find(id);return c==null?"电脑已移除":c.name();}
    private void choose(String title,List<String> names,java.util.function.IntConsumer pick){LinearLayout content=ui.column();Dialog dialog=host.sheet(title,content);for(int i=0;i<names.size();i++){final int index=i;content.addView(ui.button(names.get(i),Color.WHITE,PaneUi.INK,()->{dialog.dismiss();pick.accept(index);}));ui.gap(content,6);}}
    private void chooseComputerFilter(){List<NativeConnection> all=computers.all();List<String> names=new ArrayList<>();names.add("全部电脑");for(NativeConnection c:all)names.add(c.name());choose("筛选电脑",names,index->{computerFilter=index==0?"":all.get(index-1).computerId;host.route("tasks");});}
    private void chooseProjectFilter(){LinkedHashSet<String> paths=new LinkedHashSet<>();for(NativeTaskCatalog.Row row:NativeTaskCatalog.rows(computers.all()))if(computerFilter.isEmpty()||computerFilter.equals(row.computer.computerId))paths.add(row.cwd.isEmpty()?"(unknown)":row.cwd);List<String> values=new ArrayList<>(paths),names=new ArrayList<>();names.add("全部项目");for(String path:values)names.add("(unknown)".equals(path)?"工作目录未知":path);choose("筛选项目",names,index->{projectFilter=index==0?"":values.get(index-1);host.route("tasks");});}
    private String stateName(){switch(stateFilter){case "unfinished":return "未完成";case "running":return "运行中";case "waiting":return "待审批";case "pending":return "排队中";case "unknown":return "待核对";case "failed":return "失败";case "complete":return "已完成";default:return "全部";}}
    private void chooseStateFilter(){String[] ids={"unfinished","all","running","waiting","pending","unknown","failed","complete"};choose("筛选状态",Arrays.asList("未完成","全部","运行中","待审批","排队中","待核对","失败","已完成"),index->{stateFilter=ids[index];host.route("tasks");});}
    private LinearLayout card(String title,String subtitle){LinearLayout card=ui.card();ui.pad(card,16,16);card.addView(ui.heading(title.isEmpty()?"未命名任务":title,17));ui.gap(card,7);card.addView(ui.text(subtitle,12,PaneUi.MUTED));list.addView(card);ui.gap(list,12);return card;}
    void render(){if(list==null||"queueNew".equals(route))return;int y=scroll.getScrollY();list.removeAllViews();if("tasks".equals(route))tasks();else if("queue".equals(route))queues();else if("approvals".equals(route))approvals();else if("templates".equals(route))templates();else if("taskDetail".equals(route))detail();final ScrollView current=scroll;current.post(()->{if(current==scroll)current.scrollTo(0,y);});}
    private void tasks(){List<NativeTaskCatalog.Row> rows=NativeTaskCatalog.filter(NativeTaskCatalog.rows(computers.all()),computerFilter,projectFilter,stateFilter,query);int online=0;for(NativeConnection c:computers.all())if(c.authenticated)online++;count.setText(online+" / "+computers.all().size()+" 台电脑在线 · "+rows.size()+" 项任务");for(NativeTaskCatalog.Row row:rows){LinearLayout card=card(row.title,row.computer.name()+" · "+time(row.updatedAt)+(row.computer.authenticated?"":" · 离线缓存"));card.addView(ui.text(row.cwd.isEmpty()?"工作目录未知":row.cwd,12,PaneUi.MUTED));ui.gap(card,10);card.addView(ui.text("目标实施："+goalLabel(row.goal)+"\n实时轮次："+runtimeLabel(row.runtime)+"\n排队状态："+queueLabel(row.queue),13,PaneUi.INK));ui.gap(card,10);card.addView(ui.button("查看任务详情",PaneUi.BG,PaneUi.BLUE,()->openDetail(row)));}if(rows.isEmpty())list.addView(ui.text("此筛选下暂无任务。更换筛选，或添加排队任务。",15,PaneUi.MUTED));}
    private JSONObject queueTask(NativeConnection c,String id){JSONObject queue=c.snapshot.optJSONObject("queue");JSONArray tasks=queue==null?null:queue.optJSONArray("tasks");if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task!=null&&id.equals(task.optString("id")))return task;}return null;}
    private String send(NativeConnection c,JSONObject command){try{return c.command(command);}catch(Exception e){host.error(e.getMessage());return null;}}
    private void queues(){count.setText("每台电脑 1 个执行槽 · 待审批占用执行槽");for(NativeConnection c:computers.all()){LinearLayout header=card(c.name(),c.authenticated?"电脑在线":"离线 · 显示最后状态");if(!c.supports("taskQueue")){header.addView(ui.text("电脑需升级后才能使用任务队列",14,PaneUi.MUTED));continue;}JSONObject queue=c.snapshot.optJSONObject("queue");if(queue==null){header.addView(ui.text("等待队列快照",14,PaneUi.MUTED));continue;}boolean paused=queue.optBoolean("paused");header.addView(ui.text(paused?"已暂停派发":"按先进先出派发",15,paused?PaneUi.AMBER:PaneUi.GREEN));if(!text(queue,"pauseReason").isEmpty())header.addView(ui.text(text(queue,"pauseReason"),13,PaneUi.AMBER));Button toggle=ui.button(paused?"继续派发":"暂停派发",PaneUi.BG,PaneUi.BLUE,()->send(c,NativeConnection.obj("type","queue.pause","paused",!paused)));toggle.setContentDescription("queue.pause:"+c.computerId);toggle.setEnabled(c.authenticated);header.addView(toggle);header.addView(ui.button("添加任务",PaneUi.BG,PaneUi.BLUE,()->newTask(c,null)));JSONArray tasks=queue.optJSONArray("tasks");if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task==null)continue;LinearLayout row=card(task.optString("title"),c.name()+" · "+time(task.optLong("updatedAt")));row.addView(ui.text(queueLabel(task.optString("queueState")),15,"unknown".equals(task.optString("queueState"))?PaneUi.AMBER:PaneUi.INK));row.addView(ui.text(text(task,"cwd"),12,PaneUi.MUTED));if(!text(task,"lastError").isEmpty())row.addView(ui.text(text(task,"lastError"),13,PaneUi.RED));row.addView(ui.button("查看详情",PaneUi.BG,PaneUi.BLUE,()->openDetail(new NativeTaskCatalog.Row(c,null,task))));queueControls(row,c,task);}}}
    private void queueControls(LinearLayout parent,NativeConnection c,JSONObject task){String state=task.optString("queueState"),id=task.optString("id");if("pending".equals(state)){Button cancel=ui.button("取消待执行任务",PaneUi.BG,PaneUi.RED,()->{JSONObject current=queueTask(c,id);if(current==null||!"pending".equals(current.optString("queueState"))){host.error("任务状态已变化，请刷新核对");return;}confirm("取消排队任务？","只取消尚未派发的这一项。",()->send(c,NativeConnection.obj("type","queue.cancel","taskId",id)));});cancel.setContentDescription("queue.cancel:"+c.computerId+":"+id);cancel.setEnabled(c.authenticated);parent.addView(cancel);}else if(Arrays.asList("running","waiting").contains(state)&&!text(task,"threadId").isEmpty()&&!text(task,"turnId").isEmpty()){Button stop=ui.button("停止当前任务",PaneUi.BG,PaneUi.RED,()->confirm("停止此任务？","已完成的修改会保留。仅停止当前电脑的目标轮次。",()->{JSONObject current=queueTask(c,id);if(current==null||!text(task,"threadId").equals(text(current,"threadId"))||!text(task,"turnId").equals(text(current,"turnId"))){host.error("任务轮次已变化，请重新核对");return;}send(c,NativeConnection.obj("type","queue.stop","taskId",id,"threadId",task.getString("threadId"),"turnId",task.getString("turnId")));}));stop.setContentDescription("queue.stop:"+c.computerId+":"+id);stop.setEnabled(c.authenticated);parent.addView(stop);}else if("unknown".equals(state)){Button reconcile=ui.button("人工核对结果",PaneUi.BG,PaneUi.AMBER,()->reconcileSheet(c,task));reconcile.setEnabled(c.authenticated);parent.addView(reconcile);}}
    private interface CheckedAction {void run()throws Exception;}
    private void confirm(String title,String message,CheckedAction action){LinearLayout content=ui.column();content.addView(ui.text(message,15,PaneUi.MUTED));ui.gap(content,20);Dialog dialog=host.sheet(title,content);content.addView(ui.primary("确认",()->{dialog.dismiss();try{action.run();}catch(Exception e){host.error(e.getMessage());}}));}
    private void reconcileSheet(NativeConnection c,JSONObject task){LinearLayout content=ui.column();content.addView(ui.text("请先检查对应会话、文件和电脑上的任务。下面仅登记已核对的最终结果，不执行、不重发任务。登记后队列仍暂停，需要另行继续派发。",15,PaneUi.MUTED));ui.gap(content,18);Dialog dialog=host.sheet("人工核对执行结果",content);String[] resolutions={"completed","failed","cancelled"},labels={"已核对：完成","已核对：失败","已核对：取消"};for(int i=0;i<resolutions.length;i++){String resolution=resolutions[i];content.addView(ui.button(labels[i],PaneUi.BG,PaneUi.BLUE,()->{JSONObject current=queueTask(c,task.optString("id"));if(current==null||!"unknown".equals(current.optString("queueState"))){dialog.dismiss();host.error("状态已变化，请刷新核对");return;}if(send(c,NativeConnection.obj("type","queue.reconcile","taskId",task.optString("id"),"resolution",resolution))!=null)dialog.dismiss();}));ui.gap(content,8);}}
    private void openDetail(NativeTaskCatalog.Row row){selected=row;host.route("taskDetail");if(row.computer.authenticated&&row.computer.supports("taskDetails"))try{row.computer.requestTaskDetail(row.taskId,row.threadId);render();}catch(Exception e){host.error(e.getMessage());}}
    private boolean detailMatches(JSONObject detail){return selected!=null&&(!selected.taskId.isEmpty()?selected.taskId.equals(text(detail,"taskId")):selected.threadId.equals(text(detail,"threadId")));}
    private void detail(){if(selected==null){count.setText("请选择任务");return;}NativeConnection c=selected.computer;JSONObject detail=c.taskDetail;boolean matches=detailMatches(detail);count.setText(c.name()+" · "+time(matches?detail.optLong("updatedAt"):selected.updatedAt));LinearLayout card=card(selected.title,c.name());card.addView(ui.text(matches?text(detail,"cwd"):selected.cwd,13,PaneUi.MUTED));if(!c.supports("taskDetails"))card.addView(ui.text("电脑需升级后才能读取详细步骤与控制能力。",14,PaneUi.MUTED));else if(!matches)card.addView(ui.text(c.taskDetailRequest.isEmpty()?"详情尚未读取":"正在读取任务详情…",14,PaneUi.MUTED));if(matches){card.addView(ui.text("目标实施："+goalLabel(text(detail,"goalStatus"))+"\n实时轮次："+runtimeLabel(text(detail,"turnStatus"))+"\n排队状态："+queueLabel(text(detail,"queueState")),14,PaneUi.INK));ui.gap(card,16);card.addView(ui.heading("当前步骤",15));card.addView(ui.text(text(detail,"currentStep"),14,PaneUi.INK));if(detail.optBoolean("readOnly")||!detail.optBoolean("controllable"))card.addView(ui.text("此任务当前只可查看；其他进程的任务不能据此停止或审批。",13,PaneUi.AMBER));if(!text(detail,"lastError").isEmpty()){ui.gap(card,12);card.addView(ui.heading("最近错误",15));card.addView(ui.text(text(detail,"lastError"),13,PaneUi.RED));}JSONArray activities=detail.optJSONArray("activities");if(activities!=null)for(int i=0;i<activities.length();i++){JSONObject item=activities.optJSONObject(i);if(item==null)continue;ui.gap(card,12);card.addView(ui.heading(item.optString("title","工具活动"),14));String value=item.has("summary")?item.optString("summary"):item.has("markdown")?item.optString("markdown"):item.optString("text");TextView activity=ui.text(value,13,PaneUi.MUTED);activity.setMaxLines(8);card.addView(activity);}JSONArray approvals=detail.optJSONArray("approvals");if(approvals!=null)for(int i=0;i<approvals.length();i++){JSONObject approval=approvals.optJSONObject(i);if(approval!=null&&!detail.optBoolean("readOnly")&&detail.optBoolean("controllable"))approvalCard(card,c,approval);}}
        String thread=matches?text(detail,"threadId"):selected.threadId;if(!thread.isEmpty())card.addView(ui.button("进入关联聊天",PaneUi.BG,PaneUi.BLUE,()->host.openConversation(c,thread)));if(matches&&detail.optBoolean("controllable")){JSONObject task=queueTask(c,selected.taskId);if(task!=null)queueControls(card,c,task);}Button refresh=ui.button("刷新任务详情",PaneUi.BG,PaneUi.BLUE,()->{try{c.requestTaskDetail(selected.taskId,selected.threadId);render();}catch(Exception e){host.error(e.getMessage());}});refresh.setEnabled(c.authenticated&&c.supports("taskDetails"));card.addView(refresh);}
    private void approvals(){int total=0;for(NativeConnection c:computers.all()){JSONArray approvals=c.snapshot.optJSONArray("approvals");if(!c.supports("approvalCenter")){card(c.name(),"升级电脑后可汇总待审批项");continue;}if(approvals!=null)for(int i=0;i<approvals.length();i++){JSONObject approval=approvals.optJSONObject(i);if(approval==null)continue;total++;LinearLayout card=card(c.name(),time(approval.optLong("updatedAt"))+(c.authenticated?"":" · 离线缓存"));approvalCard(card,c,approval);}}count.setText(total+" 项待审批 · 每项单独决定");if(total==0)list.addView(ui.text("暂无待审批项。仅显示电脑配套端明确支持审批的操作。",15,PaneUi.MUTED));}
    private void approvalCard(LinearLayout card,NativeConnection c,JSONObject wrapper){JSONObject approval=wrapper.optJSONObject("approval");if(approval==null)return;ui.gap(card,10);card.addView(ui.text("会话："+text(wrapper,"threadId")+"\n目录："+text(wrapper,"cwd"),12,PaneUi.MUTED));card.addView(ui.heading(approval.optString("title","待确认操作"),15));TextView summary=ui.text(approval.optString("summary"),13,PaneUi.INK);summary.setMaxLines(5);card.addView(summary);Button review=ui.primary("核对并逐项审批",()->approvalSheet(c,wrapper));review.setEnabled(c.authenticated&&NativeTaskCatalog.approvalCurrent(c,wrapper));card.addView(review);}
    private void approvalSheet(NativeConnection c,JSONObject wrapper){if(!NativeTaskCatalog.approvalCurrent(c,wrapper)){host.error("审批已处理或版本已变化，请刷新");return;}JSONObject approval=wrapper.optJSONObject("approval");LinearLayout content=ui.column();content.addView(ui.heading(c.name(),18));content.addView(ui.text("会话："+text(wrapper,"threadId")+"\n工作目录："+text(wrapper,"cwd"),13,PaneUi.MUTED));ui.gap(content,14);TextView operation=ui.text(approval.optString("summary"),14,PaneUi.INK);operation.setTextIsSelectable(true);content.addView(operation);ui.gap(content,12);content.addView(ui.text("只处理当前版本的这一次操作，不保存永久审批许可。",12,PaneUi.AMBER));ui.gap(content,20);Dialog dialog=host.sheet("核对审批操作",content);liveApprovalDialog=dialog;liveApprovalComputer=c;liveApproval=wrapper;JSONArray choices=approval.optJSONArray("choices");if(choices!=null&&choices.length()>0){for(int i=0;i<choices.length();i++){JSONObject choice=choices.optJSONObject(i);if(choice!=null)content.addView(ui.primary(choice.optString("label"),()->decide(c,wrapper,dialog,true,choice.opt("value"))));}}else content.addView(ui.primary("仅同意本次",()->decide(c,wrapper,dialog,true,null)));ui.gap(content,8);content.addView(ui.button("拒绝",PaneUi.BG,PaneUi.RED,()->decide(c,wrapper,dialog,false,null)));}
    private void decide(NativeConnection c,JSONObject wrapper,Dialog dialog,boolean accept,Object choice){if(!NativeTaskCatalog.approvalCurrent(c,wrapper)){dialog.dismiss();host.error("审批已变化，请重新核对");return;}JSONObject approval=wrapper.optJSONObject("approval"),command=NativeConnection.obj("type","approval.decide","approvalId",approval.optString("id"),"threadId",wrapper.optString("threadId"),"version",approval.optInt("version"),"decision",accept?"accept":"decline");if(choice!=null)NativeConnection.put(command,"selection",choice);if(send(c,command)!=null)dialog.dismiss();}
    private void newTask(NativeConnection c,JSONObject template){formComputer=c.computerId;appliedTemplate=template;host.route("queueNew");}
    private void form(){NativeConnection c=computers.find(formComputer);if(c==null)c=computers.active();formOwner=c;enqueueNeedsReview=false;JSONArray records=c.requests(null);for(int i=0;i<records.length();i++){JSONObject record=records.optJSONObject(i);if(record!=null&&"queue.enqueue".equals(record.optString("type"))&&Arrays.asList("waiting","unknown","accepted").contains(record.optString("status")))enqueueNeedsReview=true;}final NativeConnection owner=c;JSONObject saved=appliedTemplate==null?c.local.section("queueDraft"):appliedTemplate;appliedTemplate=null;count.setText("在选定电脑按顺序执行；不会绕过审批");list.addView(ui.button(c.name()+" · 切换电脑",Color.WHITE,PaneUi.BLUE,()->{List<NativeConnection> all=computers.all();List<String> names=new ArrayList<>();for(NativeConnection pc:all)names.add(pc.name());choose("选择执行电脑",names,index->newTask(all.get(index),null));}));ui.gap(list,16);list.addView(ui.heading("工作目录",15));formCwd=ui.input("Windows 工作目录（必填）");formCwd.setSingleLine(true);formCwd.setText(saved.optString("cwd"));list.addView(formCwd);ui.gap(list,14);list.addView(ui.heading("任务描述",15));formText=ui.input("描述要排队执行的任务");formText.setMinLines(4);formText.setMaxLines(8);formText.setText(saved.optString("text"));list.addView(formText);ui.gap(list,14);formModel=new Spinner(activity);formModel.setContentDescription("排队任务模型");formEffort=new Spinner(activity);formEffort.setContentDescription("排队任务推理强度");list.addView(ui.text("模型",13,PaneUi.MUTED));list.addView(formModel);list.addView(ui.text("推理强度",13,PaneUi.MUTED));list.addView(formEffort);JSONArray models=c.snapshot.optJSONArray("models");List<String> modelIds=new ArrayList<>();modelIds.add("使用电脑默认模型");if(models!=null)for(int i=0;i<models.length();i++)modelIds.add(models.optJSONObject(i).optString("id"));formModel.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,modelIds));String preferredEffort=saved.optString("effort");final Spinner modelControl=formModel,effortControl=formEffort;formModel.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> v){}public void onItemSelected(AdapterView<?> v,View view,int position,long id){if(formOwner!=owner||formModel!=modelControl)return;List<String> efforts=new ArrayList<>();efforts.add("默认强度");if(position>0&&models!=null){JSONArray values=models.optJSONObject(position-1).optJSONArray("efforts");if(values!=null)for(int i=0;i<values.length();i++)efforts.add(values.optString(i));}effortControl.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,efforts));int selected=efforts.indexOf(preferredEffort);if(selected>=0)effortControl.setSelection(selected);}});int model=modelIds.indexOf(saved.optString("model"));formModel.setSelection(Math.max(0,model));TextWatcher watch=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){handler.removeCallbacks(saveFormLater);handler.postDelayed(saveFormLater,250);}public void afterTextChanged(Editable e){}};formCwd.addTextChangedListener(watch);formText.addTextChangedListener(watch);ui.gap(list,20);enqueueButton=ui.primary("加入这台电脑的队列",()->enqueue(owner));enqueueButton.setEnabled(owner.authenticated&&owner.supports("taskQueue")&&pendingEnqueue.isEmpty());list.addView(enqueueButton);ui.gap(list,10);list.addView(ui.button("保存为模板",Color.WHITE,PaneUi.BLUE,this::saveTemplateSheet));ui.gap(list,12);if(!owner.supports("taskQueue"))list.addView(ui.text("电脑需升级至支持任务队列的版本。",14,PaneUi.AMBER));list.addView(ui.text("队列保存在电脑。断线只查询操作回执，不自动重复入队；结果不明时可在电脑的操作记录中核对。",13,PaneUi.MUTED));}
    private JSONObject formValue(){String model=formModel==null||formModel.getSelectedItemPosition()<=0?"":String.valueOf(formModel.getSelectedItem()),effort=formEffort==null||formEffort.getSelectedItemPosition()<=0?"":String.valueOf(formEffort.getSelectedItem());return NativeConnection.obj("cwd",formCwd==null?"":formCwd.getText().toString().trim(),"text",formText==null?"":formText.getText().toString(),"model",model,"effort",effort);}
    void saveInputs(){handler.removeCallbacks(saveFormLater);if(formOwner!=null&&formCwd!=null&&formText!=null)try{formOwner.local.save("queueDraft",formValue());}catch(Exception e){host.error("排队任务草稿保存失败");}}
    private void enqueue(NativeConnection c){if(enqueueNeedsReview){confirm("确认另一次入队？","先在操作记录和队列核对前一次请求。确认后将生成新的请求，此操作不会撤销前一次任务。",()->{enqueueNeedsReview=false;enqueue(c);});return;}JSONObject form=formValue();if(text(form,"cwd").isEmpty()||text(form,"text").trim().isEmpty()){host.error("请填写工作目录和任务描述");return;}saveInputs();JSONObject command=NativeConnection.obj("type","queue.enqueue","cwd",text(form,"cwd"),"text",text(form,"text"));if(!text(form,"model").isEmpty())NativeConnection.put(command,"model",text(form,"model"));if(!text(form,"effort").isEmpty())NativeConnection.put(command,"effort",text(form,"effort"));String request=send(c,command);if(request!=null){pendingEnqueue=request;pendingComputer=c.computerId;pendingForm=form;enqueueButton.setEnabled(false);enqueueButton.setText("等待入队回执…");}}
    private void saveTemplateSheet(){if(formOwner==null)return;final NativeConnection c=formOwner;final JSONObject value=formValue();LinearLayout content=ui.column();EditText name=ui.input("模板名称");content.addView(name);ui.gap(content,15);content.addView(ui.text("只保存目录、提示词、模型和强度，不保存审批许可。",13,PaneUi.MUTED));Dialog dialog=host.sheet("保存任务模板",content);content.addView(ui.primary("保存模板",()->{try{NativeConnection.put(value,"name",name.getText().toString());NativeTaskTemplates.save(c.local,value);dialog.dismiss();Toast.makeText(activity,"模板已加密保存",Toast.LENGTH_SHORT).show();}catch(Exception e){name.setError(e.getMessage());}}));}
    private void templates(){count.setText("模板分别存于各电脑配置 · 本机加密保存");int total=0;for(NativeConnection c:computers.all()){JSONArray templates=NativeTaskTemplates.list(c.local);for(int i=0;i<templates.length();i++){JSONObject template=templates.optJSONObject(i);if(template==null)continue;total++;LinearLayout card=card(template.optString("name"),c.name());card.addView(ui.text(template.optString("cwd"),13,PaneUi.MUTED));TextView preview=ui.text(template.optString("text"),14,PaneUi.INK);preview.setMaxLines(3);card.addView(preview);card.addView(ui.text(template.optString("model")+" · "+template.optString("effort"),12,PaneUi.MUTED));card.addView(ui.button("用模板创建排队任务",PaneUi.BG,PaneUi.BLUE,()->newTask(c,template)));card.addView(ui.button("删除模板",PaneUi.BG,PaneUi.RED,()->confirm("删除此模板？","仅移除当前电脑配置中的这个模板，已有队列不变。",()->{NativeTaskTemplates.remove(c.local,template.getString("id"));render();})));}}if(total==0)list.addView(ui.text("暂无模板。在添加排队任务页面填写内容后，可保存为模板。",15,PaneUi.MUTED));}
    private boolean sameForm(JSONObject a,JSONObject b){if(a==null||b==null)return false;for(String field:new String[]{"cwd","text","model","effort"})if(!text(a,field).equals(text(b,field)))return false;return true;}
    void changed(JSONObject event){if("taskDetail".equals(route)&&selected!=null&&selected.computer.computerId.equals(event.optString("computerId"))&&Arrays.asList("turn.status","item.upsert","approval.request").contains(event.optString("type"))&&selected.threadId.equals(event.optString("threadId"))){final NativeTaskCatalog.Row expected=selected;handler.postDelayed(()->{if(selected==expected&&"taskDetail".equals(route)&&expected.computer.authenticated&&expected.computer.taskDetailRequest.isEmpty())try{expected.computer.requestTaskDetail(expected.taskId,expected.threadId);}catch(Exception ignored){}},400);}
if(liveApprovalDialog!=null&&liveApprovalDialog.isShowing()&&(!liveApprovalComputer.authenticated||!NativeTaskCatalog.approvalCurrent(liveApprovalComputer,liveApproval))){liveApprovalDialog.dismiss();liveApprovalDialog=null;Toast.makeText(activity,"审批已由其他设备处理或版本更新",Toast.LENGTH_LONG).show();}
        if(!pendingEnqueue.isEmpty()&&pendingComputer.equals(event.optString("computerId"))){
            NativeConnection owner=computers.find(pendingComputer);
            if("connection".equals(event.optString("type"))&&(owner==null||!owner.authenticated)){pendingEnqueue="";pendingComputer="";enqueueNeedsReview=true;if(enqueueButton!=null)enqueueButton.setText("结果待核对 · 另一次入队前确认");}
            else if(pendingEnqueue.equals(event.optString("requestId"))&&"command.result".equals(event.optString("type"))){boolean ok=event.optBoolean("ok");pendingEnqueue="";pendingComputer="";enqueueNeedsReview=!ok;
                if(ok&&owner!=null){boolean same=sameForm(owner.local.section("queueDraft"),pendingForm);if(same)try{owner.local.save("queueDraft",new JSONObject());}catch(Exception ignored){}if(formOwner==owner&&sameForm(formValue(),pendingForm)){formCwd=null;formText=null;host.route("queue");}}
                else if(enqueueButton!=null)enqueueButton.setText("结果待核对 · 另一次入队前确认");pendingForm=null;
            }
        }
        if("queueNew".equals(route)){if(enqueueButton!=null&&pendingEnqueue.isEmpty())enqueueButton.setEnabled(formOwner!=null&&formOwner.authenticated&&formOwner.supports("taskQueue"));return;}render();
    }
}
